async def act(page):
    """Locate the 'Archives' widget and click the 'December 2017' link.

    Strategy:
    - Navigate to the site root ('/') because the Archives widget is commonly present there.
    - Use accessible role-based selectors to find a container that has a heading 'Archives'.
    - Scope the search for a link named 'December 2017' inside that container, with sensible fallbacks.
    - Click the link as the final action (it will navigate away).
    """
    # Navigate to site root where Archives is typically present
    await page.goto("/")
    await page.wait_for_load_state("networkidle")

    candidate_roles = [
        "complementary",
        "aside",
        "region",
        "section",
        "navigation",
    ]

    archives_container = None

    # Try to find a container that contains a heading named 'Archives'
    for role_name in candidate_roles:
        try:
            cand = page.get_by_role(role_name).filter(has=page.get_by_role("heading", name="Archives"))
            if await cand.count() > 0:
                archives_container = cand
                break
        except Exception:
            # localized failure for this role lookup; continue to next
            continue

    # Fallback: find the heading first and then find a nearby container that contains it
    if archives_container is None:
        heading = page.get_by_role("heading", name="Archives")
        if await heading.count() > 0:
            for role_name in candidate_roles:
                try:
                    scoped = page.get_by_role(role_name).filter(has=heading)
                    if await scoped.count() > 0:
                        archives_container = scoped
                        break
                except Exception:
                    continue

    link_locator = None

    # If we have an archives container, search inside it for the December 2017 link
    if archives_container is not None:
        try:
            candidate_link = archives_container.get_by_role("link", name="December 2017")
            if await candidate_link.count() > 0:
                link_locator = candidate_link
            else:
                # sometimes links are nested inside listitems within the widget
                try:
                    listitem_links = archives_container.get_by_role("listitem").get_by_role("link", name="December 2017")
                    if await listitem_links.count() > 0:
                        link_locator = listitem_links
                except Exception:
                    pass
        except Exception:
            link_locator = None

    # Global fallback: search the whole page for the link
    if link_locator is None or await link_locator.count() == 0:
        global_link = page.get_by_role("link", name="December 2017")
        if await global_link.count() > 0:
            link_locator = global_link

    if link_locator is None or await link_locator.count() == 0:
        raise Exception("Could not find an 'Archives' widget or a link named 'December 2017' on the site.")

    # Click the December 2017 link (final action; expected to navigate away)
    await link_locator.first.click()

